// 3つのサービスが共通で参照する共有パッケージ。
// Understanding Code Dependencies が「どのパッケージが共有されているか」を
// どう検出するかを確認するために配置している。
const crypto = require('node:crypto');

function newOrderId() {
  return `ord-${crypto.randomUUID()}`;
}

function log(message, context = {}) {
  console.log(JSON.stringify({ message, service: process.env.AWS_LAMBDA_FUNCTION_NAME, ...context }));
}

module.exports = { newOrderId, log };
